IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[interface_request_log]') AND type IN ('U'))
	DROP TABLE [dbo].[interface_request_log]
GO

CREATE TABLE [dbo].[interface_request_log] (
  [id] varchar(64) COLLATE Chinese_PRC_CI_AS  NOT NULL,
  [create_by] varchar(64) COLLATE Chinese_PRC_CI_AS  NULL,
  [create_time] datetime  NULL,
  [update_by] varchar(64) COLLATE Chinese_PRC_CI_AS  NULL,
  [update_time] datetime  NULL,
  [interface_code] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [interface_name] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [patient_no] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [pat_id] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [success] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [send_message] text COLLATE Chinese_PRC_CI_AS  NULL,
  [receive_message] text COLLATE Chinese_PRC_CI_AS  NULL,
  [remark] text COLLATE Chinese_PRC_CI_AS  NULL,
  [patient_name] varchar(255) COLLATE Chinese_PRC_CI_AS  NULL
)
GO

